// SPDX-License-Identifier: GPL-3.0-only
//! `THIRD-PARTY-LICENSES` reproduces the licence notices of the Rust crates the
//! shipped binaries link, and every package must carry it. The file is
//! generated by `scripts/third-party-licenses.py` from the locked
//! normal-dependency closure, which needs cargo and the crate sources; CI runs
//! that script's `check` mode. This suite needs neither: it keeps the
//! checked-in file in step with `Cargo.lock` (every locked crate is either
//! listed as linked, with its licence text, or as not linked, at the locked
//! version) and keeps each package definition in step with the file.
//!
//! Platform behavior: pure file reads on every OS.

use std::collections::{BTreeMap, BTreeSet};
use std::path::PathBuf;

const FILE: &str = "THIRD-PARTY-LICENSES";
const CRATES_BEGIN: &str = "=== CRATES ===";
const UNLINKED_BEGIN: &str = "=== NOT LINKED ===";
const TEXTS_BEGIN: &str = "=== LICENCE TEXTS ===";
const STANDARD_BEGIN: &str = "=== STANDARD TEXTS ===";
const END_MARK: &str = "=== END ===";

fn read(relative: &str) -> String {
    std::fs::read_to_string(PathBuf::from(env!("CARGO_MANIFEST_DIR")).join(relative))
        .unwrap_or_else(|error| panic!("read {relative}: {error}"))
}

/// Every `[[package]]` of Cargo.lock except the root package, as (name, version).
fn locked_crates() -> BTreeSet<(String, String)> {
    let mut crates = BTreeSet::new();
    let (mut name, mut version) = (None::<String>, None::<String>);
    let mut flush = |name: &mut Option<String>, version: &mut Option<String>| {
        if let (Some(n), Some(v)) = (name.take(), version.take())
            && n != "odytty"
        {
            crates.insert((n, v));
        }
    };
    for line in read("Cargo.lock").lines() {
        if line == "[[package]]" {
            flush(&mut name, &mut version);
        } else if let Some(value) = line.strip_prefix("name = ") {
            name = Some(value.trim_matches('"').to_owned());
        } else if let Some(value) = line.strip_prefix("version = ") {
            version = Some(value.trim_matches('"').to_owned());
        }
    }
    flush(&mut name, &mut version);
    crates
}

struct Parsed {
    /// (name, version) -> text ids or standard-text licence ids.
    linked: BTreeMap<(String, String), Vec<String>>,
    standard_ids_used: BTreeSet<String>,
    unlinked: BTreeSet<(String, String)>,
    text_headings: BTreeSet<String>,
    applies_to: BTreeMap<String, BTreeSet<String>>,
    standard_headings: BTreeSet<String>,
    header_linked: usize,
    header_texts: usize,
}

fn parse() -> Parsed {
    let text = read(FILE);
    assert!(
        text.trim_end().ends_with(END_MARK),
        "{FILE} does not end with {END_MARK}"
    );
    let mut parsed = Parsed {
        linked: BTreeMap::new(),
        standard_ids_used: BTreeSet::new(),
        unlinked: BTreeSet::new(),
        text_headings: BTreeSet::new(),
        applies_to: BTreeMap::new(),
        standard_headings: BTreeSet::new(),
        header_linked: 0,
        header_texts: 0,
    };
    let mut section = "header";
    let mut current_text: Option<String> = None;
    for line in text.lines() {
        match line {
            CRATES_BEGIN => section = "crates",
            UNLINKED_BEGIN => section = "unlinked",
            TEXTS_BEGIN => section = "texts",
            STANDARD_BEGIN => section = "standard",
            END_MARK => section = "end",
            _ => {}
        }
        match section {
            "header" => {
                if let Some(count) = line.strip_prefix("linked crates: ") {
                    parsed.header_linked = count.trim().parse().expect("crate count");
                } else if let Some(count) = line.strip_prefix("licence texts: ") {
                    parsed.header_texts = count.trim().parse().expect("text count");
                }
            }
            "crates" => {
                if let Some(rest) = line.strip_prefix("crate: ") {
                    let fields: Vec<&str> = rest.split(" | ").collect();
                    let mut head = fields[0].split(' ');
                    let key = (
                        head.next().expect("name").to_owned(),
                        head.next().expect("version").to_owned(),
                    );
                    let references: Vec<String> = fields
                        .iter()
                        .find_map(|field| {
                            field
                                .strip_prefix("texts: ")
                                .or_else(|| field.strip_prefix("standard text: "))
                        })
                        .map(|ids| ids.split(' ').map(str::to_owned).collect())
                        .unwrap_or_default();
                    if fields.iter().any(|f| f.starts_with("standard text: ")) {
                        parsed.standard_ids_used.extend(references.iter().cloned());
                    }
                    assert!(
                        parsed.linked.insert(key.clone(), references).is_none(),
                        "{key:?} listed twice"
                    );
                }
            }
            "unlinked" => {
                if let Some(rest) = line.strip_prefix("unlinked: ") {
                    let mut parts = rest.split(' ');
                    parsed.unlinked.insert((
                        parts.next().expect("name").to_owned(),
                        parts.next().expect("version").to_owned(),
                    ));
                }
            }
            "texts" => {
                if let Some(id) = line
                    .strip_prefix("--- ")
                    .and_then(|rest| rest.strip_suffix(" ---"))
                {
                    parsed.text_headings.insert(id.to_owned());
                    current_text = Some(id.to_owned());
                } else if let (Some(rest), Some(id)) =
                    (line.strip_prefix("Applies to: "), current_text.as_ref())
                {
                    parsed
                        .applies_to
                        .insert(id.clone(), rest.split(", ").map(str::to_owned).collect());
                }
            }
            "standard" => {
                if let Some(id) = line
                    .strip_prefix("--- ")
                    .and_then(|rest| rest.strip_suffix(" ---"))
                {
                    parsed.standard_headings.insert(id.to_owned());
                }
            }
            _ => {}
        }
    }
    parsed
}

#[test]
fn the_file_accounts_for_every_locked_crate_at_its_locked_version() {
    let parsed = parse();
    let locked = locked_crates();
    let linked: BTreeSet<(String, String)> = parsed.linked.keys().cloned().collect();
    assert!(
        linked.is_disjoint(&parsed.unlinked),
        "a crate is both linked and not linked"
    );
    let listed: BTreeSet<(String, String)> = linked.union(&parsed.unlinked).cloned().collect();
    let stale: Vec<_> = listed.difference(&locked).collect();
    let missing: Vec<_> = locked.difference(&listed).collect();
    assert!(
        stale.is_empty() && missing.is_empty(),
        "{FILE} is out of step with Cargo.lock (run `python3 scripts/third-party-licenses.py generate`): \
         listed but not locked {stale:?}, locked but not listed {missing:?}"
    );
    assert!(!linked.is_empty());
    assert_eq!(parsed.header_linked, linked.len(), "linked crate count");
    assert_eq!(
        parsed.header_texts,
        parsed.text_headings.len(),
        "text count"
    );
}

#[test]
fn every_linked_crate_has_its_licence_text_and_every_text_is_used() {
    let parsed = parse();
    let mut referenced = BTreeSet::new();
    for (key, references) in &parsed.linked {
        assert!(!references.is_empty(), "{key:?} carries no licence text");
        for reference in references {
            if parsed.standard_ids_used.contains(reference) {
                assert!(
                    parsed.standard_headings.contains(reference),
                    "{key:?}: no standard text for {reference}"
                );
            } else {
                assert!(
                    parsed.text_headings.contains(reference),
                    "{key:?}: no licence text {reference}"
                );
                assert!(
                    parsed.applies_to[reference].contains(&format!("{} {}", key.0, key.1)),
                    "{reference} does not list {key:?}"
                );
                referenced.insert(reference.clone());
            }
        }
    }
    assert_eq!(
        referenced, parsed.text_headings,
        "a licence text applies to no crate"
    );
    assert_eq!(
        parsed.standard_ids_used, parsed.standard_headings,
        "a standard text is unused or missing"
    );
}

#[test]
fn every_package_definition_ships_the_file() {
    let manifest = read("Cargo.toml");
    let deb = manifest
        .split("[package.metadata.deb]")
        .nth(1)
        .and_then(|rest| rest.split("[package.metadata.generate-rpm]").next())
        .expect("deb section");
    let rpm = manifest
        .split("[package.metadata.generate-rpm]")
        .nth(1)
        .and_then(|rest| {
            rest.split("[package.metadata.generate-rpm.requires]")
                .next()
        })
        .expect("rpm section");
    assert!(
        deb.contains(
            "[\"THIRD-PARTY-LICENSES\", \"usr/share/doc/odytty/THIRD-PARTY-LICENSES\", \"644\"]"
        ),
        "the deb does not ship {FILE}"
    );
    assert!(
        rpm.contains("{ source = \"THIRD-PARTY-LICENSES\", dest = \"/usr/share/doc/odytty/THIRD-PARTY-LICENSES\", mode = \"644\" }"),
        "the rpm does not ship {FILE}"
    );
    for (file, needle) in [
        (
            "dist/aur/PKGBUILD",
            "install -Dm644 THIRD-PARTY-LICENSES \"$pkgdir/usr/share/doc/$pkgname/THIRD-PARTY-LICENSES\"",
        ),
        (
            "dist/linux/tarball-install.sh",
            "for notice in LICENSE NOTICE THIRD-PARTY-LICENSES; do",
        ),
        (
            "dist/macos/make-app.sh",
            "\"$ROOT/THIRD-PARTY-LICENSES\" \"$APP/Contents/Resources/licenses/\"",
        ),
        (
            "dist/appimage/build-appimage.sh",
            "cp LICENSE NOTICE THIRD-PARTY-LICENSES \"$APPDIR/usr/share/licenses/odytty/\"",
        ),
        (
            ".github/workflows/release.yml",
            "Copy-Item README.md, LICENSE, NOTICE, THIRD-PARTY-LICENSES dist/windows/package/",
        ),
        (
            ".github/workflows/dev-build.yml",
            "Copy-Item README.md, LICENSE, NOTICE, THIRD-PARTY-LICENSES dist/windows/package/",
        ),
        (
            ".github/workflows/release.yml",
            "cp README.md LICENSE NOTICE THIRD-PARTY-LICENSES \"dist/build/${stage}/\"",
        ),
    ] {
        assert!(read(file).contains(needle), "{file} does not ship {FILE}");
    }
}

#[test]
fn the_generator_is_run_by_ci() {
    let ci = read(".github/workflows/ci.yml");
    assert!(
        ci.contains("python3 scripts/third-party-licenses.py check"),
        "CI does not check {FILE} against the locked closure"
    );
}
